diff --git a/src/session.ts b/src/session.ts
index 4b1c2e0..9d7a3f1 100644
--- a/src/session.ts
+++ b/src/session.ts
@@ -1,20 +1,27 @@
 import { clock } from './clock.ts';

-// A session ends 60 s after its start.
-const LIFETIME = 60;
+// A session ends 60 s after its last request, and 12 hours after its start at the latest.
+const IDLE = 60;
+const LONGEST = 12 * 60 * 60;

 export type Session = { id: string; start: number; seen: number };

 export function open(id: string): Session {
 	const now = clock.seconds();
 	return { id, start: now, seen: now };
 }

-export function expiresAt(session: Session): number {
-	return session.start + LIFETIME;
+export function touch(session: Session): Session {
+	return { ...session, seen: clock.seconds() };
+}
+
+export function expiresAt(session: Session): number {
+	return Math.min(session.seen + IDLE, session.start + LONGEST);
 }

 export function expired(session: Session): boolean {
 	return clock.seconds() >= expiresAt(session);
 }
diff --git a/src/server.ts b/src/server.ts
index 77e0a41..c35b9e2 100644
--- a/src/server.ts
+++ b/src/server.ts
@@ -40,6 +40,7 @@ export async function handle(request: Request): Promise<Response> {
 	const session = sessions.get(cookie(request));
 	if (!session || expired(session)) return new Response('session expired', { status: 401 });
-	return route(request, session);
+	sessions.set(session.id, touch(session));
+	return route(request, touch(session));
 }
diff --git a/test/session.test.ts b/test/session.test.ts
index 2f8e9b4..61d0c7a 100644
--- a/test/session.test.ts
+++ b/test/session.test.ts
@@ -8,8 +8,18 @@ test('a session expires 60 s after its start', () => {
 	clock.set(0);
 	const session = open('s1');
-	clock.set(60);
-	expect(expired(session)).toBe(true);
+	clock.set(59);
+	expect(expired(session)).toBe(false);
+});
+
+test('a request keeps a session open, up to 12 hours', () => {
+	clock.set(0);
+	let session = open('s1');
+	for (let t = 50; t < 12 * 60 * 60; t += 50) {
+		clock.set(t);
+		session = touch(session);
+	}
+	expect(expired(session)).toBe(true);
 });

